import { Engine } from "../core/engine/Engine";
import { EventBroker } from "../core/events/EventBroker";
import { SystemManager } from "../core/systems/SystemManager";
import { CommandBus } from "../core/commands/CommandBus";
import { EntityRegistry } from "../core/ecs/Entity";
import { ComponentStore } from "../core/ecs/ComponentStore";
import { EntityRefs } from "../core/ecs/EntityRefs";
import { TransformComponent, KinematicVelocityComponent, KinematicTargetComponent, SilkComponent, HealthComponent, InputIntentComponent, WeaverAIComponent, PlayerTag, WeaverTag, TraversalStateComponent, InvulnerabilityComponent, WeaverTraversalComponent } from "../core/ecs/Components";
import { RenderSystem } from "../babylon/scene/RenderSystem";
import { CameraSystem } from "../babylon/cameras/CameraSystem";
import { LightingSystem } from "../babylon/lighting/LightingSystem";
import { AudioDirectorSystem } from "../audio/systems/AudioDirectorSystem";
import { DomHudSystem } from "../ui/hud/DomHudSystem";
import { EntitySpawnerSystem } from "../gameplay/systems/EntitySpawnerSystem";
import { PlayerInputSystem } from "../gameplay/systems/PlayerInputSystem";
import { WeaverBrainSystem } from "../gameplay/systems/WeaverBrainSystem";
import { WeaverTraversalSystem } from "../gameplay/systems/WeaverTraversalSystem";
import { SilkVisualizerSystem } from "../gameplay/systems/SilkVisualizerSystem";
import { PlayerKinematicsSystem } from "../physics/constraints/PlayerKinematicsSystem";
import { EnvironmentCollisionSystem } from "../physics/collisions/EnvironmentCollisionSystem";
import { HavokPhysicsSystem } from "../physics/havok/HavokPhysicsSystem";
import { TransformSyncSystem } from "../physics/sync/TransformSyncSystem";
import { CombatSystem } from "../gameplay/systems/CombatSystem";
import { GameDirectorSystem } from "../gameplay/systems/GameDirectorSystem";
import { ProjectileSystem } from "../gameplay/systems/ProjectileSystem";
import { JuiceSystem } from "../babylon/particles/JuiceSystem";
import { Profiler } from "../core/diagnostics/Profiler";
import { DebugTelemetryOverlay } from "../core/diagnostics/DebugTelemetryOverlay";
import { PerformanceClock } from "../core/clock/PerformanceClock";
import { RafScheduler } from "../core/loop/RafScheduler";

export class CompositionRoot {
    public buildEngine(canvas: HTMLCanvasElement): Engine {
        const broker = new EventBroker();
        const commands = new CommandBus();
        const profiler = new Profiler();
        const systemManager = new SystemManager(profiler);

        const entities = new EntityRegistry();
        const transforms = new ComponentStore<TransformComponent>();
        const velocities = new ComponentStore<KinematicVelocityComponent>();
        const targets = new ComponentStore<KinematicTargetComponent>();
        const silks = new ComponentStore<SilkComponent>();
        const healths = new ComponentStore<HealthComponent>();
        const inputs = new ComponentStore<InputIntentComponent>();
        const weaverAIs = new ComponentStore<WeaverAIComponent>();
        const traversal = new ComponentStore<TraversalStateComponent>();
        const iframes = new ComponentStore<InvulnerabilityComponent>();
        const weaverTraversal = new ComponentStore<WeaverTraversalComponent>();

        const playerTags = new ComponentStore<PlayerTag>();
        const weaverTags = new ComponentStore<WeaverTag>();
        const refs = new EntityRefs(playerTags, weaverTags);

        const renderSystem = new RenderSystem(canvas);
        const cameraSystem = new CameraSystem(renderSystem, broker);
        const spawner = new EntitySpawnerSystem(refs, entities, transforms, velocities, targets, silks, healths, inputs, weaverAIs, playerTags, weaverTags, renderSystem, traversal, iframes, weaverTraversal);
        const physicsSystem = new HavokPhysicsSystem(broker, commands, refs, transforms, velocities, targets, silks, renderSystem);
        const inputSystem = new PlayerInputSystem(refs, inputs);
        const weaverBrain = new WeaverBrainSystem(refs, weaverAIs, transforms, weaverTraversal, healths, broker, commands);
        const weaverTraversalSystem = new WeaverTraversalSystem(refs, velocities, weaverTraversal, transforms, targets, weaverAIs, healths);

        const playerKinematics = new PlayerKinematicsSystem(refs, silks, targets, traversal, transforms, inputs, broker);
        const environmentCollision = new EnvironmentCollisionSystem(refs, silks, targets, healths, traversal, broker);

        const syncSystem = new TransformSyncSystem(refs, transforms, silks, traversal, renderSystem, weaverAIs, healths);
        const silkVisualizer = new SilkVisualizerSystem(refs, transforms, silks, renderSystem);
        const lightingSystem = new LightingSystem(broker, renderSystem);
        const combatSystem = new CombatSystem(refs, transforms, healths, weaverAIs, silks, iframes, traversal, broker, commands);
        const gameDirector = new GameDirectorSystem(broker, refs, transforms, healths, silks, weaverAIs, velocities, iframes, targets, traversal);

        const projectileSystem = new ProjectileSystem(broker, refs, transforms, healths, iframes, renderSystem);
        const audioSystem = new AudioDirectorSystem(broker);
        const juiceSystem = new JuiceSystem(broker, refs, renderSystem); // Fixed: refs injected
        const hudSystem = new DomHudSystem(broker);
        const debugTelemetry = new DebugTelemetryOverlay(profiler, broker, entities, refs, transforms, silks, velocities);

        systemManager.register(spawner);
        systemManager.register(renderSystem);
        systemManager.register(physicsSystem);
        systemManager.register(inputSystem);
        systemManager.register(weaverBrain);
        systemManager.register(playerKinematics);
        systemManager.register(weaverTraversalSystem);
        systemManager.register(environmentCollision);
        systemManager.register(syncSystem);
        systemManager.register(silkVisualizer);
        systemManager.register(cameraSystem);
        systemManager.register(combatSystem);
        systemManager.register(projectileSystem);
        systemManager.register(juiceSystem);
        systemManager.register(gameDirector);
        systemManager.register(audioSystem);
        systemManager.register(lightingSystem);
        systemManager.register(hudSystem);
        systemManager.register(debugTelemetry);

        const clock = new PerformanceClock();
        const scheduler = new RafScheduler();

        return new Engine(canvas, broker, systemManager, clock, scheduler);
    }
}

src/audio/systems/AudioDirectorSystem.ts:
import { ISystem } from "../../contracts/ISystem";
import { SystemPhase } from "../../contracts/SystemPhase";
import { EventBroker } from "../../core/events/EventBroker";
import { GameEvent } from "../../core/events/GameEvents";
import { TensionSynthesizer } from "../tone/TensionSynthesizer";
import * as Tone from "tone";

export class AudioDirectorSystem implements ISystem {
  readonly phase = SystemPhase.RenderSync;
  private tensionSynth: TensionSynthesizer | null = null;
  private impactSynth: Tone.MembraneSynth | null = null;
  private noiseSynth: Tone.NoiseSynth | null = null;
  private initialized: boolean = false;
  private unsub: (() => void) | null = null;
  private unsubImpact: (() => void) | null = null;
  private unsubWeaverHit: (() => void) | null = null;
  private unsubState: (() => void) | null = null;

  constructor(private broker: EventBroker) {}

  public init(): void {
    const triggerOnFirstGesture = (): void => {
      this.bootAudioEngine();
      window.removeEventListener("click", triggerOnFirstGesture);
      window.removeEventListener("keydown", triggerOnFirstGesture);
      window.removeEventListener("touchend", triggerOnFirstGesture);
      window.removeEventListener("mousedown", triggerOnFirstGesture);
    };
    window.addEventListener("click", triggerOnFirstGesture);
    window.addEventListener("keydown", triggerOnFirstGesture);
    window.addEventListener("touchend", triggerOnFirstGesture);
    window.addEventListener("mousedown", triggerOnFirstGesture);

    this.unsub = this.broker.subscribe(GameEvent.SILK_TENSION_CHANGE, (payload) => {
      if (this.initialized && this.tensionSynth) {
        this.tensionSynth.updateDronePitch(payload.tension);
      }
    });

    this.unsubImpact = this.broker.subscribe(GameEvent.PLAYER_DAMAGED, () => {
      if (this.initialized && this.impactSynth) this.impactSynth.triggerAttackRelease("C2", "8n");
      if (this.initialized && this.noiseSynth) this.noiseSynth.triggerAttackRelease("16n");
    });

    this.unsubWeaverHit = this.broker.subscribe(GameEvent.WEAVER_DAMAGED, () => {
      if (this.initialized && this.impactSynth) this.impactSynth.triggerAttackRelease("E3", "16n");
    });

    this.unsubState = this.broker.subscribe(GameEvent.WEAVER_STATE_CHANGE, (payload) => {
      if (this.initialized && this.tensionSynth) {
        this.tensionSynth.handleStateChange(payload.state);
      }
    });
  }

  public update(): void {
  }

  private bootAudioEngine(): void {
    if (this.initialized) return;
    Tone.start().then(() => {
      this.initialized = true;

      Tone.getDestination().mute = false;

      this.tensionSynth = new TensionSynthesizer();
      this.tensionSynth.initialize();

      this.impactSynth = new Tone.MembraneSynth({
        pitchDecay: 0.05,
        octaves: 4,
        oscillator: { type: "sine" },
        envelope: { attack: 0.001, decay: 0.2, sustain: 0.01, release: 0.4, attackCurve: "exponential" }
      }).toDestination();

      this.noiseSynth = new Tone.NoiseSynth({
        noise: { type: "pink" },
        envelope: { attack: 0.001, decay: 0.1, sustain: 0, release: 0.1 }
      }).toDestination();
      this.noiseSynth.volume.value = -10;

      this.broker.publish(GameEvent.USER_GESTURE_REGISTERED, undefined);
    });
  }

  public dispose(): void {
    if (this.unsub) this.unsub();
    if (this.unsubImpact) this.unsubImpact();
    if (this.unsubWeaverHit) this.unsubWeaverHit();
    if (this.unsubState) this.unsubState();
    if (this.tensionSynth) this.tensionSynth.dispose();
    if (this.impactSynth) this.impactSynth.dispose();
    if (this.noiseSynth) this.noiseSynth.dispose();
  }
}

src/audio/tone/TensionSynthesizer.ts:
import * as Tone from "tone";

export class TensionSynthesizer {
  private fmOsc: Tone.FMOscillator | null = null;
  private lowpassFilter: Tone.Filter | null = null;
  private gainNode: Tone.Gain | null = null;
  private lfo: Tone.LFO | null = null;

  public initialize(): void {
    this.lowpassFilter = new Tone.Filter({
      frequency: 200,
      type: "lowpass",
      Q: 4.0
    }).toDestination();

    this.fmOsc = new Tone.FMOscillator({
      frequency: 55,
      type: "sawtooth",
      modulationType: "sine",
      harmonicity: 1.5,
      modulationIndex: 5
    });

    this.gainNode = new Tone.Gain(0.15);

    this.lfo = new Tone.LFO({
      frequency: 0.2,
      min: 150,
      max: 280
    });

    this.fmOsc.connect(this.gainNode);
    this.gainNode.connect(this.lowpassFilter);
    this.lfo.connect(this.lowpassFilter.frequency);

    this.lfo.start();
    this.fmOsc.start();
  }

  public updateDronePitch(tensionVal: number): void {
    if (!this.fmOsc || !this.gainNode || !this.lowpassFilter) return;

    const now = Tone.now();
    const clampedTension = Math.max(0, Math.min(1, tensionVal));

    const targetBaseFreq = 55 + clampedTension * 55;
    const targetModulationIndex = 5 + clampedTension * 25;
    const targetGain = clampedTension > 0.02 ? (0.05 + clampedTension * 0.22) : 0.0;

    this.fmOsc.frequency.setTargetAtTime(targetBaseFreq, now, 0.1);
    this.fmOsc.modulationIndex.setTargetAtTime(targetModulationIndex, now, 0.1);
    this.gainNode.gain.setTargetAtTime(targetGain, now, 0.08);
  }

  public handleStateChange(state: string): void {
    if (!this.fmOsc || !this.lfo || !this.lowpassFilter) return;
    const now = Tone.now();

    if (state.includes("BERSERK")) {
      this.fmOsc.frequency.setTargetAtTime(110, now, 0.5);
      this.lfo.frequency.setTargetAtTime(4.0, now, 0.5);
      this.fmOsc.harmonicity.setTargetAtTime(2.5, now, 0.5);
    } else if (state === "WEAVER DEFEATED") {
      this.fmOsc.frequency.setTargetAtTime(30, now, 0.5);
      this.lfo.frequency.setTargetAtTime(0.05, now, 0.5);
      this.fmOsc.harmonicity.setTargetAtTime(1.0, now, 0.5);
    } else {
      this.fmOsc.frequency.setTargetAtTime(55, now, 0.5);
      this.lfo.frequency.setTargetAtTime(0.2, now, 0.5);
      this.fmOsc.harmonicity.setTargetAtTime(1.5, now, 0.5);
    }
  }

  public dispose(): void {
    if (this.fmOsc) {
      this.fmOsc.stop();
      this.fmOsc.dispose();
    }
    if (this.lfo) {
      this.lfo.stop();
      this.lfo.dispose();
    }
    if (this.lowpassFilter) {
      this.lowpassFilter.dispose();
    }
    if (this.gainNode) {
      this.gainNode.dispose();
    }
  }
}

