import { ISystem } from "../../contracts/ISystem";
import { SystemPhase } from "../../contracts/SystemPhase";
import { ComponentStore } from "../../core/ecs/ComponentStore";
import { WeaverAIComponent, TransformComponent, WeaverTraversalComponent, HealthComponent } from "../../core/ecs/Components";
import { EntityRefs } from "../../core/ecs/EntityRefs";
import { EventBroker } from "../../core/events/EventBroker";
import { GameEvent } from "../../core/events/GameEvents";
import { CommandBus } from "../../core/commands/CommandBus";
import { IWeaverState, AIContext, WeaverStateType } from "../states/IWeaverState";
import { WeaverSweepingState, WeaverDashingState, WeaverReturningState, WeaverDefeatedState } from "../states/WeaverStates";

export class WeaverBrainSystem implements ISystem {
  readonly phase = SystemPhase.Intents;
  private states = new Map<WeaverStateType, IWeaverState>();
  private activeState: IWeaverState | null = null;
  private contextCache: AIContext | null = null;
  private unsubDamage: (() => void) | null = null;

  constructor(
    private refs: EntityRefs,
    private ai: ComponentStore<WeaverAIComponent>,
    private transforms: ComponentStore<TransformComponent>,
    private weaverTraversal: ComponentStore<WeaverTraversalComponent>,
    private healths: ComponentStore<HealthComponent>,
    private broker: EventBroker,
    private commands: CommandBus
  ) {
    this.states.set("SWEEPING", new WeaverSweepingState());
    this.states.set("DASHING", new WeaverDashingState());
    this.states.set("RETURNING", new WeaverReturningState());
    this.states.set("DEFEATED", new WeaverDefeatedState());
  }

  public init(): void {
    const aiComp = this.ai.get(this.refs.weaver);
    if (aiComp) {
      const startState = aiComp.state as WeaverStateType;
      const stateObj = this.states.get(startState) || this.states.get("SWEEPING")!;

      aiComp.state = stateObj.type;
      aiComp.hue = stateObj.hue;
      aiComp.timeInState = 0;

      this.activeState = stateObj;

      this.contextCache = {
        weaverId: this.refs.weaver,
        playerId: this.refs.player,
        ai: aiComp,
        transforms: this.transforms,
        weaverTraversal: this.weaverTraversal,
        healths: this.healths,
        commands: this.commands,
        broker: this.broker
      };

      this.activeState.enter(this.contextCache);
      this.publishStateChangeEvent(stateObj.name, stateObj.hue);
    }

    this.unsubDamage = this.broker.subscribe(GameEvent.WEAVER_DAMAGED, () => {
      const aiComp = this.ai.get(this.refs.weaver);
      const health = this.healths.get(this.refs.weaver);
      if (aiComp && health) {
        if (health.current <= 0) {
          this.transitionTo("DEFEATED");
        } else if (aiComp.state === "SWEEPING") {
          this.transitionTo("DASHING");
        }
      }
    });
  }

  private publishStateChangeEvent(name: string, hue: string): void {
    const health = this.healths.get(this.refs.weaver);
    const isBerserk = health ? (health.current < health.max * 0.5) : false;
    let finalName = name;
    if (isBerserk && this.activeState?.type !== "DEFEATED") {
      finalName = `${name} (BERSERK)`;
    }
    this.broker.publish(GameEvent.WEAVER_STATE_CHANGE, { 
      state: finalName, 
      hue: hue 
    });
  }

  private transitionTo(nextStateKey: WeaverStateType): void {
    const aiComp = this.ai.get(this.refs.weaver);
    if (!aiComp || !this.contextCache || !this.activeState) return;

    const nextStateObj = this.states.get(nextStateKey);
    if (nextStateObj && nextStateKey !== this.activeState.type) {
      this.activeState.exit(this.contextCache);

      aiComp.state = nextStateObj.type;
      aiComp.hue = nextStateObj.hue;
      aiComp.timeInState = 0;

      this.activeState = nextStateObj;
      this.activeState.enter(this.contextCache);

      this.publishStateChangeEvent(nextStateObj.name, nextStateObj.hue);
    }
  }

  public update(dt: number): void {
    const aiComp = this.ai.get(this.refs.weaver);
    if (!aiComp || !this.activeState) return;

    if (!this.contextCache) {
      this.contextCache = {
        weaverId: this.refs.weaver,
        playerId: this.refs.player,
        ai: aiComp,
        transforms: this.transforms,
        weaverTraversal: this.weaverTraversal,
        healths: this.healths,
        commands: this.commands,
        broker: this.broker
      };
    }

    const nextStateKey = this.activeState.update(this.contextCache, dt);

    if (nextStateKey && nextStateKey !== this.activeState.type) {
      this.transitionTo(nextStateKey);
    }
  }

  public dispose(): void {
    if (this.unsubDamage) {
      this.unsubDamage();
    }
  }
}

src/gameplay/systems/WeaverTraversalSyst:
import { ISystem } from "../../contracts/ISystem";
import { SystemPhase } from "../../contracts/SystemPhase";
import { ComponentStore } from "../../core/ecs/ComponentStore";
import { KinematicVelocityComponent, WeaverTraversalComponent, TransformComponent, KinematicTargetComponent, WeaverAIComponent, HealthComponent } from "../../core/ecs/Components";
import { EntityRefs } from "../../core/ecs/EntityRefs";

export class WeaverTraversalSystem implements ISystem {
readonly phase = SystemPhase.Kinematics;
private minX = -13.0;
private maxX = 13.0;

constructor(
private refs: EntityRefs,
private velocities: ComponentStore<KinematicVelocityComponent>,
private traversal: ComponentStore<WeaverTraversalComponent>,
private transforms: ComponentStore<TransformComponent>,
private targets: ComponentStore<KinematicTargetComponent>,
private aiStore: ComponentStore<WeaverAIComponent>,
private healths: ComponentStore<HealthComponent>
) {}

public update(dt: number): void {
const vel = this.velocities.get(this.refs.weaver);
const trav = this.traversal.get(this.refs.weaver);
const trans = this.transforms.get(this.refs.weaver);
const target = this.targets.get(this.refs.weaver);
const ai = this.aiStore.get(this.refs.weaver);
const health = this.healths.get(this.refs.weaver);

if (!vel || !trav || !trans || !target) return;

const isSweeping = !ai || ai.state === "SWEEPING";
if (isSweeping) {
let nextX = trans.x + vel.x * dt;
const isBerserk = health ? (health.current < health.max * 0.5) : false;
const sweepSpeed = isBerserk ? 9.0 : 4.5;
if (nextX >= this.maxX) {
nextX = this.maxX;
vel.x = -sweepSpeed;
} else if (nextX <= this.minX) {
nextX = this.minX;
vel.x = sweepSpeed;
}
target.x = nextX;
target.y = 28.0;
target.active = true;
trav.velX = vel.x;
trav.velY = 0;
} else {
target.x = trans.x + vel.x * dt;
target.y = trans.y + vel.y * dt;
target.active = true;
trav.velX = vel.x;
trav.velY = vel.y;
}

const wallLimit = 13.8;
if (target.x > wallLimit) {
target.x = wallLimit;
if (vel.x > 0) vel.x = 0;
} else if (target.x < -wallLimit) {
target.x = -wallLimit;
if (vel.x < 0) vel.x = 0;
}

const ceilingLimit = 32.0;
const floorLimit = -8.0;
if (target.y > ceilingLimit) {
target.y = ceilingLimit;
if (vel.y > 0) vel.y = 0;
trav.isGrounded = false;
trav.isWallClinging = false;
} else if (target.y < floorLimit) {
target.y = floorLimit;
if (vel.y < 0) vel.y = 0;
trav.isGrounded = true;
trav.isWallClinging = false;
} else {
trav.isGrounded = false;
const wallThreshold = 13.6;
if (Math.abs(target.x) >= wallThreshold) {
trav.isWallClinging = true;
trav.wallNormalX = target.x > 0 ? -1 : 1;
} else {
trav.isWallClinging = false;
trav.wallNormalX = 0;
}
}
}
}

