src/physics/constraints/PlayerKinematics:
import { ISystem } from "../../contracts/ISystem";
import { SystemPhase } from "../../contracts/SystemPhase";
import { ComponentStore } from "../../core/ecs/ComponentStore";
import {
    SilkComponent,
    KinematicTargetComponent,
    TraversalStateComponent,
    TransformComponent,
    InputIntentComponent
} from "../../core/ecs/Components";
import { EntityRefs } from "../../core/ecs/EntityRefs";
import { EventBroker } from "../../core/events/EventBroker";
import { GameEvent } from "../../core/events/GameEvents";

export class PlayerKinematicsSystem implements ISystem {
    readonly phase = SystemPhase.Kinematics;

    private readonly GRAVITY             = -24.0;
    private readonly SWING_STEER_FORCE   = 36.0; 
    private readonly LAUNCH_STEER_FORCE  = 16.0;

    private readonly BASE_SILK_LENGTH    = 10.0;
    private readonly MAX_SILK_LENGTH     = 24.0;

    private readonly WALL_LIMIT_X        = 14.2;
    private readonly WALL_SLIDE_SPEED    = -3.0;
    private readonly DRAG_DAMPING        = 0.99;

    private readonly TENSION_CHARGE_RATE = 0.38; // Upgraded: charges slower
    private readonly MIN_FLING_TENSION   = 0.06;

    private readonly FLING_IMPULSE       = 76.0; // Upgraded: launches with massive speed
    private readonly LAUNCH_DURATION     = 0.70;
    private readonly LAUNCH_GRAVITY_MULT = 0.22;

    private lastTraversalState: string = "";

    constructor(
        private refs: EntityRefs,
        private silks: ComponentStore<SilkComponent>,
        private targets: ComponentStore<KinematicTargetComponent>,
        private traversal: ComponentStore<TraversalStateComponent>,
        private transforms: ComponentStore<TransformComponent>,
        private inputs: ComponentStore<InputIntentComponent>,
        private broker: EventBroker
    ) {}

    public update(dt: number): void {
        const silk = this.silks.get(this.refs.player);
        const target  = this.targets.get(this.refs.player);
        const trav    = this.traversal.get(this.refs.player);
        const wTrans  = this.transforms.get(this.refs.weaver);
        const input   = this.inputs.get(this.refs.player);

        if (!silk || !target || !trav || !wTrans || !input) return;

        silk.anchorX = wTrans.x;
        silk.anchorY = wTrans.y;
        silk.anchorZ = wTrans.z;

        let nextX = target.x;
        let nextY = target.y;

        if (trav.state === "LAUNCHING") {
            trav.launchTimer -= dt;
            silk.dynamicVelX += input.x * this.LAUNCH_STEER_FORCE * dt;
            silk.dynamicVelY += this.GRAVITY * this.LAUNCH_GRAVITY_MULT * dt;

            const damp = Math.pow(this.DRAG_DAMPING, dt * 60);
            silk.dynamicVelX *= damp;
            silk.dynamicVelY *= damp;

            nextX += silk.dynamicVelX * dt;
            nextY += silk.dynamicVelY * dt;

            if (trav.launchTimer <= 0) {
                trav.state = "AIRBORNE";
                trav.wallDir = 0;
            }
        } else {
            silk.dynamicVelY += this.GRAVITY * dt;

            if (trav.state === "AIRBORNE") {
                silk.dynamicVelX += input.x * this.SWING_STEER_FORCE * dt;
            }

            const damp = Math.pow(this.DRAG_DAMPING, dt * 60);
            silk.dynamicVelX *= damp;
            silk.dynamicVelY *= damp;

            nextX += silk.dynamicVelX * dt;
            nextY += silk.dynamicVelY * dt;
        }

        this.resolveWallContact(nextX, nextY, dt, target, silk, trav, input);

        if (trav.state === "AIRBORNE" || trav.state === "LAUNCHING") {
            this.enforcePendulumConstraint(target, silk);
        }

        const dx = target.x - silk.anchorX;
        const dy = target.y - silk.anchorY;
        silk.currentLength = Math.sqrt(dx * dx + dy * dy) || 1.0;

        this.broker.publish(GameEvent.SILK_TENSION_CHANGE, { tension: silk.tension });

        if (trav.state !== this.lastTraversalState) {
            this.lastTraversalState = trav.state;
            this.broker.publish(GameEvent.PLAYER_STATE_CHANGE, { state: trav.state });
        }
    }

    private resolveWallContact(
        nextX: number,
        nextY: number,
        dt: number,
        target: KinematicTargetComponent,
        silk: SilkComponent,
        trav: TraversalStateComponent,
        input: InputIntentComponent
    ): void {
        const hitRight = nextX >  this.WALL_LIMIT_X;
        const hitLeft  = nextX < -this.WALL_LIMIT_X;
        const wallDir  = hitRight ? 1 : hitLeft ? -1 : 0;

        if (trav.state === "WALL_SLIDING") {
            const stillPressingIn = input.x === trav.wallDir;

            if (!stillPressingIn) {
                this.triggerFling(silk, target, trav);
                return;
            }

            target.x = trav.wallDir * this.WALL_LIMIT_X;
            target.y = nextY;
            silk.dynamicVelX = 0;
            silk.dynamicVelY = Math.max(silk.dynamicVelY, this.WALL_SLIDE_SPEED);

            silk.tension = Math.min(1.0, silk.tension + this.TENSION_CHARGE_RATE * dt);
            const maxStretch = this.MAX_SILK_LENGTH - this.BASE_SILK_LENGTH;
            silk.maxLength = this.BASE_SILK_LENGTH + silk.tension * maxStretch;

            if (input.jump) {
                this.triggerFling(silk, target, trav);
                input.jump = false;
            }
            return;
        }

        if (wallDir !== 0) {
            const pressingIn = input.x === wallDir;

            if (pressingIn) {
                trav.state    = "WALL_SLIDING";
                trav.wallDir  = wallDir;
                trav.wallNormalX = -wallDir;
                trav.wallNormalY = 0;

                target.x = wallDir * this.WALL_LIMIT_X;
                target.y = nextY;
                silk.dynamicVelX = 0;
                silk.dynamicVelY = Math.max(silk.dynamicVelY, this.WALL_SLIDE_SPEED);

                silk.tension = Math.min(1.0, silk.tension + this.TENSION_CHARGE_RATE * dt);
                const maxStretch = this.MAX_SILK_LENGTH - this.BASE_SILK_LENGTH;
                silk.maxLength = this.BASE_SILK_LENGTH + silk.tension * maxStretch;
            } else {
                target.x = wallDir * this.WALL_LIMIT_X;
                target.y = nextY;
                if (Math.sign(silk.dynamicVelX) === wallDir) {
                    silk.dynamicVelX *= -0.2; 
                }
                trav.state   = "AIRBORNE";
                trav.wallDir = 0;
                silk.tension = Math.max(0, silk.tension - 4.0 * dt);
            }
            return;
        }

        // --- FIXED FALLBACK PROTECTION ---
        // Only fall back to AIRBORNE if we are not actively in the middle of a LAUNCH
        if (trav.state !== "LAUNCHING") {
            trav.state = "AIRBORNE";
        }
        trav.wallDir = 0;
        silk.tension = Math.max(0, silk.tension - 4.0 * dt);
        target.x = nextX;
        target.y = nextY;
    }

    private triggerFling(
        silk: SilkComponent,
        target: KinematicTargetComponent,
        trav: TraversalStateComponent
    ): void {
        const storedTension = silk.tension;
        silk.tension  = 0.0;

        if (storedTension < this.MIN_FLING_TENSION) {
            trav.state      = "AIRBORNE";
            trav.wallDir    = 0;
            trav.launchPower = 0;
            return;
        }

        const dx   = silk.anchorX - target.x;
        const dy   = silk.anchorY - target.y;
        const dist = Math.sqrt(dx * dx + dy * dy) || 1;

        const power = storedTension * this.FLING_IMPULSE;
        silk.dynamicVelX = (dx / dist) * power;
        silk.dynamicVelY = (dy / dist) * power;

        trav.state       = "LAUNCHING";
        trav.launchTimer = this.LAUNCH_DURATION;
        trav.launchPower = storedTension;
        trav.wallDir     = 0;

        this.broker.publish(GameEvent.CAMERA_SHAKE_TRIGGERED, {
            amplitude: 0.25 + storedTension * 0.35,
            duration: 0.2
        });
    }

    private enforcePendulumConstraint(target: KinematicTargetComponent, silk: SilkComponent): void {
        const dx = target.x - silk.anchorX;
        const dy = target.y - silk.anchorY;
        const dist = Math.sqrt(dx * dx + dy * dy) || 1.0;

        if (dist < silk.maxLength) {
            silk.maxLength = Math.max(this.BASE_SILK_LENGTH, dist);
        }

        if (dist > silk.maxLength) {
            const nx = dx / dist;
            const ny = dy / dist;

            target.x = silk.anchorX + nx * silk.maxLength;
            target.y = silk.anchorY + ny * silk.maxLength;

            const dot = silk.dynamicVelX * nx + silk.dynamicVelY * ny;
            if (dot > 0) {
                silk.dynamicVelX -= dot * nx;
                silk.dynamicVelY -= dot * ny;
            }
        }
    }
}

src/physics/havok/HavokPhysicsSystem.ts:
import { ISystem } from "../../contracts/ISystem";
import { SystemPhase, InitPhase } from "../../contracts/SystemPhase";
import { IReadablePhysics, PhysicsTransform } from "../../contracts/IPhysicsWorld";
import { EventBroker } from "../../core/events/EventBroker";
import { GameEvent } from "../../core/events/GameEvents";
import { CommandBus } from "../../core/commands/CommandBus";
import { ComponentStore } from "../../core/ecs/ComponentStore";
import { TransformComponent, KinematicVelocityComponent, KinematicTargetComponent, SilkComponent } from "../../core/ecs/Components";
import { EntityRefs } from "../../core/ecs/EntityRefs";
import { EntityId } from "../../core/ecs/Entity";
import { SetKinematicVelocityCommand, ApplyImpulseCommand, SetSilkMaxLengthCommand, SetSilkAttachedCommand } from "../commands/PhysicsCommands";
import { IVisualRegistry } from "../../contracts/IVisualRegistry";
import * as BABYLON from "@babylonjs/core";
import HavokPhysics from "@babylonjs/havok";

export class HavokPhysicsSystem implements ISystem, IReadablePhysics {
readonly phase = SystemPhase.PhysicsStep;
readonly initPhase = InitPhase.Bootstrap;
private havokPlugin: BABYLON.HavokPlugin | null = null;

constructor(
private broker: EventBroker,
private commands: CommandBus,
private refs: EntityRefs,
private transforms: ComponentStore<TransformComponent>,
private velocities: ComponentStore<KinematicVelocityComponent>,
private targets: ComponentStore<KinematicTargetComponent>,
private silks: ComponentStore<SilkComponent>,
private visualRegistry: IVisualRegistry
) {}

public async init(): Promise<void> {
this.registerCommands();
const scene = this.visualRegistry.getScene();
if (scene) {
try {
const havokInstance = await HavokPhysics({
locateFile: () => "https://cdn.babylonjs.com/havok/HavokPhysics.wasm"
});
this.havokPlugin = new BABYLON.HavokPlugin(true, havokInstance);
scene.enablePhysics(new BABYLON.Vector3(0, -9.81, 0), this.havokPlugin);
console.log("[HavokPhysicsSystem] Havok initialized successfully from CDN.");

const physFloor = BABYLON.MeshBuilder.CreateBox("physFloor", { width: 34, height: 1.0, depth: 6 }, scene);
physFloor.position.set(0, -8.5, 0);
physFloor.isVisible = false;
new BABYLON.PhysicsAggregate(physFloor, BABYLON.PhysicsShapeType.BOX, { mass: 0, friction: 0.8, restitution: 0.2 }, scene);

const physLeft = BABYLON.MeshBuilder.CreateBox("physLeft", { width: 1.0, height: 140, depth: 6 }, scene);
physLeft.position.set(-15.5, 14, 0);
physLeft.isVisible = false;
new BABYLON.PhysicsAggregate(physLeft, BABYLON.PhysicsShapeType.BOX, { mass: 0, friction: 0.8 }, scene);

const physRight = BABYLON.MeshBuilder.CreateBox("physRight", { width: 1.0, height: 140, depth: 6 }, scene);
physRight.position.set(15.5, 14, 0);
physRight.isVisible = false;
new BABYLON.PhysicsAggregate(physRight, BABYLON.PhysicsShapeType.BOX, { mass: 0, friction: 0.8 }, scene);
} catch (err) {
console.warn("[HavokPhysicsSystem] Failed to load Havok WASM. Standing by with visual physics fallback.", err);
}
}
}

private registerCommands(): void {
this.commands.register<SetKinematicVelocityCommand>("SET_KINEMATIC_VELOCITY", (cmd) => {
const vel = this.velocities.get(cmd.entityId);
if (vel) { vel.x = cmd.x; vel.y = cmd.y; vel.z = cmd.z; }
});
this.commands.register<ApplyImpulseCommand>("APPLY_IMPULSE", (cmd) => {
if (cmd.entityId === this.refs.player) {
const silk = this.silks.get(this.refs.player);
if (silk) { silk.dynamicVelX += cmd.x; silk.dynamicVelY += cmd.y; }
}
});
this.commands.register<SetSilkMaxLengthCommand>("SET_SILK_MAX_LENGTH", (cmd) => {
const silk = this.silks.get(this.refs.player);
if (silk) silk.maxLength = cmd.length;
});
this.commands.register<SetSilkAttachedCommand>("SET_SILK_ATTACHED", (cmd) => {
const silk = this.silks.get(this.refs.player);
if (silk) silk.isAttached = cmd.attached;
});
}

public update(): void {
this.commands.flush();
for (const [, curr] of this.transforms.entries()) {
curr.prevX = curr.x; curr.prevY = curr.y; curr.prevZ = curr.z;
curr.prevQx = curr.qx; curr.prevQy = curr.qy; curr.prevQz = curr.qz; curr.prevQw = curr.qw;
}
const pTarget = this.targets.get(this.refs.player);
const pTrans = this.transforms.get(this.refs.player);
if (pTrans && pTarget && pTarget.active) {
pTrans.x = pTarget.x; pTrans.y = pTarget.y; pTrans.z = pTarget.z;
}
const wTarget = this.targets.get(this.refs.weaver);
const wTrans = this.transforms.get(this.refs.weaver);
if (wTrans && wTarget && wTarget.active) {
wTrans.x = wTarget.x; wTrans.y = wTarget.y; wTrans.z = wTarget.z;
}
const silk = this.silks.get(this.refs.player);
if (silk) {
this.broker.publish(GameEvent.SILK_TENSION_CHANGE, { tension: silk.tension });
this.broker.publish(GameEvent.SILK_LENGTH_CHANGE, { length: silk.currentLength, maxLength: silk.maxLength });
}
}

public getTransform(id: EntityId): PhysicsTransform | null {
const t = this.transforms.get(id);
return t ? { x: t.x, y: t.y, z: t.z, qx: t.qx, qy: t.qy, qz: t.qz, qw: t.qw } : null;
}

public getPreviousTransform(id: EntityId): PhysicsTransform | null {
const t = this.transforms.get(id);
return t ? { x: t.prevX, y: t.prevY, z: t.prevZ, qx: t.prevQx, qy: t.prevQy, qz: t.prevQz, qw: t.prevQw } : null;
}
}

